/* A reviewed source-to-plan workflow. Public course metadata is separate from earned coursework. */
let catalogSourcePromises=new Map(),catalogPrepared=null,catalogDraftEpoch=0;
async function catalogProgramRecord(id){if(id.startsWith('uw'))return(await getUWCurricula()).records.find(r=>r.id===id);if(id.startsWith('wsu-catalog-')){if(!catalogSourcePromises.has('wsu'))catalogSourcePromises.set('wsu',fetch('wsu-curricula.json').then(r=>{if(!r.ok)throw Error('WSU source snapshot unavailable.');return r.json()}).catch(e=>{catalogSourcePromises.delete('wsu');throw e}));return(await catalogSourcePromises.get('wsu')).records.find(r=>r.id===id)}throw Error('This program has no structured source snapshot yet. Use its official source and enter the checklist.')}
async function startCatalogDraft(id){const epoch=++catalogDraftEpoch;try{const record=await catalogProgramRecord(id);if(!record)throw Error('Program source not found.');if(epoch!==catalogDraftEpoch)return;const proposal=CatalogDraftCore.proposal(record);proposal.title=record.title;proposal.sourceRecordId=id;proposal.rows=proposal.rows.map(r=>({...r,text:r.text.slice(0,8000),textTruncated:r.text.length>8000}));state.catalogDraft={...proposal,approvals:{},creditSelections:{},goalId:(state.degreeGoals||[]).find(g=>g.programId===id)?.id||'',updatedAt:new Date().toISOString()};catalogPrepared=null;save();location.hash='catalog-draft';render()}catch(error){toast(error.message)}}
function catalogDraftPage(){const draft=state.catalogDraft;if(!draft)return journeyPage(3,'Build from your actual catalog.',`<p class="journey-lede">Choose a UW or WSU credential, then open its published requirements and build a source-based draft.</p><a class="btn primary" href="#programs">Choose a program →</a>`,'degrees');return journeyPage(3,'Turn source requirements into your next steps.',`<p class="journey-lede">${esc(draft.title)} · ${esc(draft.institution)} · ${esc(draft.units)} credits</p>${draft.planningPhase?`<p class="quiet-note">Course-only scope: ${esc(draft.planningPhase==='admission'?'Admission preparation':draft.planningPhase==='entry'?'Before-enrollment preparation':'Degree courses')} · Applicant route: ${esc(draft.applicantRoute||'unknown')}. This does not establish completion of the full program.</p>`:''}<p>Review explicit course clauses below. The planner can add documented course prerequisites and propose an order. Unparsed rules, placement, credit categories and policies remain visible; they are never assumed satisfied.</p><a class="journey-secondary" href="${esc(draft.source)}" target="_blank" rel="noopener">Open the official source ↗</a><section class="degree-optimizer"><h2>1. Confirm the clauses you want to plan</h2><p>Confirmation means you checked the source and your catalog year. It is not institutional approval. Leave uncertain clauses unchecked and use the full source for context.</p><div class="catalog-clause-list">${draft.rows.map((r,i)=>`<article class="catalog-clause ${r.kind==='review'?'needs-review':''}"><span class="eyebrow">${r.kind==='review'?'POLICY / CATEGORY / AMBIGUOUS CLAUSE':r.kind==='all'?'ALL LISTED COURSES':'COURSE CHOICE'}</span><div class="catalog-source-excerpt">${esc(r.text)}</div>${r.textTruncated?'<p>Excerpt shortened for workspace storage. Open the complete source.</p>':''}${r.codes.length?`<p>${r.kind==='all'?'All listed':r.count+' of the listed'}: ${r.codes.map(esc).join(' · ')}</p>${r.kind==='choose'?`<label>Select ${r.count} option(s)<select data-catalog-row-options="${i}" ${r.count>1?'multiple':''}><option value="">Choose documented course(s)</option>${r.codes.map(code=>`<option value="${esc(code)}" ${(r.selectedCodes||[]).includes(code)?'selected':''}>${esc(code)}</option>`).join('')}</select></label>`:''}<label><input type="checkbox" data-confirm-catalog-row="${i}" ${r.confirmed?'checked':''}> I checked this course clause and its context for my catalog year.</label>`:'<p class="quiet-note">Kept as an unresolved condition. Enter the approved courses/constraints in the connected degree editor after reviewing this clause.</p>'}${r.footnotes?.length?`<details><summary>Source footnotes / exceptions</summary>${r.footnotes.map(n=>`<p>${esc(n)}</p>`).join('')}</details>`:''}</article>`).join('')}</div><button class="btn primary" id="prepare-catalog-courses">Load course rules & propose a draft</button><div id="catalog-course-review" aria-live="polite"></div></section><p class="plan-trust-alert">A partial source draft is useful for early preparation, but cannot establish full degree completion, admission, residency or class access. Missing metadata and unresolved prerequisites block affected imports until reviewed.</p>`,'degrees')}
async function prepareCatalogCourses(){const target=document.querySelector('#catalog-course-review'),draft=state.catalogDraft;if(!target||!draft)return;const confirmed=draft.rows.filter(r=>r.confirmed&&r.codes.length);if(!confirmed.length)return toast('Confirm at least one explicit course clause first.');target.innerHTML='<p role="status">Loading the selected subjects and their published prerequisite rules…</p>';try{const records=await CourseCatalogStore.loadClosure(draft.institution,[...confirmed.flatMap(r=>r.kind==='choose'?r.selectedCodes||[]:r.codes),...Object.values(draft.approvals||{}).flatMap(a=>a.dependencies||[])]);if(!target.isConnected||state.catalogDraft!==draft)return;const outcome=CatalogDraftCore.construct(draft,records,state.courses.filter(E.passing),{approvals:draft.approvals,credits:draft.creditSelections});catalogPrepared={draft,records,outcome};renderCatalogCourseReview(target)}catch(error){if(target.isConnected)target.innerHTML=`<p role="alert">${esc(error.message)}</p>`}}
function renderCatalogCourseReview(target){const {draft,records,outcome}=catalogPrepared;const courseIssues=outcome.review.filter(r=>r.code),policyIssues=outcome.review.filter(r=>!r.code);target.innerHTML=`<h2>2. Check prerequisite paths and remaining conditions</h2><p>${outcome.courses.length} unique source course entries, including prerequisites. ${policyIssues.length} clauses remain outside the automatic draft; ${courseIssues.length} course condition(s) need review.</p>${courseIssues.map(r=>{const code=CatalogDraftCore.norm(r.code),meta=records.find(c=>CatalogDraftCore.norm(c.code)===code);return `<article class="degree-goal"><h3>${esc(r.code)}</h3><p>${esc(r.text)}</p>${meta?`<a class="journey-secondary" href="${esc(meta.source)}" target="_blank" rel="noopener">Official course rule ↗</a><label>Earlier required course codes, if the unparsed rule needs a specific course path<input data-catalog-dependencies="${esc(code)}" value="${esc((draft.approvals?.[code]?.dependencies||[]).join(', '))}" placeholder="Exact codes separated by commas"></label><label><input type="checkbox" data-catalog-course-confirm="${esc(code)}" ${draft.approvals?.[code]?.confirmed?'checked':''}> I checked this source condition and confirmed my placement/eligibility or the entered course path.</label>${!Number.isFinite(meta.credits)||meta.credits<=0?`<label>Verified planned credits<input type="number" min="0.5" max="30" step="0.5" data-catalog-credits="${esc(code)}" value="${esc(draft.creditSelections?.[code]||'')}"></label>`:''}`:'<p>No exact metadata is loaded. Add the official course in the connected-degree editor; this unresolved course cannot be imported automatically.</p>'}</article>`}).join('')}<details><summary>Proposed course order inputs and prerequisite choices</summary>${outcome.courses.map(c=>`<article class="degree-goal"><h3>${esc(c.code)} · ${esc(c.title)}</h3><p>${c.credits} ${esc(c.units.toLowerCase())} credits · ${c.foundation?'Foundation / early preparation.':''}</p><p>${esc(c.sourcePrerequisiteText||'No formal prerequisite is listed in this snapshot.')}</p><p>Earlier: ${c.prereqs.map(k=>outcome.courses.find(x=>MultiDegree.key(x)===k)?.code||k).map(esc).join(', ')||'None in the selected path'} · Same-term allowed: ${c.coreqs.map(k=>outcome.courses.find(x=>MultiDegree.key(x)===k)?.code||k).map(esc).join(', ')||'None'}</p><a href="${esc(c.source)}" target="_blank" rel="noopener">Course source ↗</a></article>`).join('')}</details><button class="btn" id="recheck-catalog-draft">Recheck selected paths</button><label><input id="acknowledge-partial-draft" type="checkbox"> I understand unmodeled source clauses remain unresolved and this draft is not a full degree audit.</label><button class="btn primary" id="import-catalog-draft" ${courseIssues.length||outcome.missing.length?'disabled':''}>Import reviewed course draft →</button>`;target.querySelectorAll('[data-catalog-dependencies]').forEach(el=>el.onchange=()=>{draft.approvals||={};draft.approvals[el.dataset.catalogDependencies]||={};draft.approvals[el.dataset.catalogDependencies].dependencies=el.value.split(',').map(s=>s.trim().toUpperCase()).filter(Boolean);save()});target.querySelectorAll('[data-catalog-course-confirm]').forEach(el=>el.onchange=()=>{draft.approvals||={};draft.approvals[el.dataset.catalogCourseConfirm]||={};draft.approvals[el.dataset.catalogCourseConfirm].confirmed=el.checked;save()});target.querySelectorAll('[data-catalog-credits]').forEach(el=>el.onchange=()=>{draft.creditSelections||={};draft.creditSelections[el.dataset.catalogCredits]=+el.value;save()});target.querySelector('#recheck-catalog-draft').onclick=prepareCatalogCourses;target.querySelector('#import-catalog-draft').onclick=()=>{if(!target.querySelector('#acknowledge-partial-draft').checked)return toast('Acknowledge the remaining scope before importing this draft.');importCatalogDraft()}}
function importCatalogDraft(){const prepared=catalogPrepared;if(!prepared||prepared.draft!==state.catalogDraft)return toast('Recheck the current draft first.');const {draft,outcome}=prepared;if(outcome.review.some(r=>r.code)||outcome.missing.length)return toast('Resolve the course conditions before importing.');const id=draft.goalId||degreeIds(),old=(state.degreeGoals||[]).find(g=>g.id===id);if(old?.requirements.length&&!confirm('Replace this goal’s planning checklist with this source-based course draft? Academic records stay unchanged.'))return;if(!old&&(state.degreeGoals||[]).length>=6)return toast('Use up to six goals.');const pool=new Map((state.degreeCourses||[]).map(c=>[MultiDegree.key(c),c]));for(const c of outcome.courses){const prior=pool.get(MultiDegree.key(c));if(prior&&prior.credits!==c.credits)return toast('Credit mismatch for '+c.code+'. Review existing alternatives before importing.');pool.set(MultiDegree.key(c),{...prior,...c})}const requirements=outcome.requirements.flatMap(r=>{if(r.count<=8&&r.choices.length<=12)return[r];if(r.count===r.choices.length)return r.choices.map((key,i)=>({...r,id:r.id+'-'+i,label:r.label.slice(0,120)+' · '+(i+1),count:1,choices:[key]}));return[]});if(requirements.length!==outcome.requirements.length&&outcome.requirements.some(r=>r.count!==r.choices.length&&r.choices.length>12))return toast('A source choice group exceeds this draft limit. Enter its approved selections manually.');const goal={...old,id,name:draft.title,institution:draft.institution,programId:draft.programId,source:draft.source,kind:old?.kind||'Source-based degree draft',role:old?.role||((state.degreeGoals||[]).some(g=>g.role==='primary')?'concurrent':'primary'),catalogYear:old?.catalogYear||'Confirm applicable catalog year',sharing:old?.sharing||'review',advisorConfirmed:old?.advisorConfirmed||false,requirements,preset:'catalog-source-draft',auditScope:outcome.scope,unresolvedSourceClauses:outcome.review.filter(r=>!r.code).map(r=>r.text.slice(0,8000)),notes:['Source clauses and course paths were reviewed by the student; not an institution-approved degree audit.','Prerequisite alternatives are proposed choices, not a global fastest-graduation proof. Actual offerings and eligibility require registration review.','Unmodeled categories, totals, GPA, residency, exceptions and admission conditions remain unresolved; see the source review below.']};const candidates=[...(state.degreeGoals||[]).filter(g=>g.id!==id),goal],errors=MultiDegree.validate(candidates,[...pool.values()]);if(errors.length)return toast(errors[0]);state.degreeGoals=candidates;state.degreeCourses=[...pool.values()];save();location.hash='degrees';render();toast('Source-based course draft imported; unresolved policies remain visible.')}
async function showWSURequirements(id,target){target.hidden=false;target.innerHTML='<p role="status">Opening the official WSU schedule of studies…</p>';try{const record=await catalogProgramRecord(id);if(!target.isConnected)return;if(!record)throw Error('No exact WSU program source found.');target.innerHTML=`<span class="eyebrow">OFFICIAL WSU CATALOG SNAPSHOT · ${esc(record.checked)}</span><h3>${esc(record.title)}</h3><p>${record.totalCredits||'Review source'} semester credits shown by source. Confirm the applicable catalog year and offering campus.</p><a class="journey-secondary" href="${esc(record.source)}" target="_blank" rel="noopener">Official catalog ↗</a><div class="uw-source-text" tabindex="0">${esc((record.narrative||'').replace(/\\r\\n/g,'\n'))}</div><div class="table-wrap"><table><thead><tr><th>Source year/term</th><th>Course or category</th><th>Credits shown</th></tr></thead><tbody>${record.scheduleOfStudies.map(row=>`<tr><td>Year ${row.year} · ${row.term===1?'Fall':row.term===2?'Spring':'Term '+row.term}</td><td>${esc(row.label)}${row.footnotes.length?`<details><summary>Conditions</summary>${row.footnotes.map(n=>`<p>${esc(n)}</p>`).join('')}</details>`:''}</td><td>${esc(row.creditsPhrase)}</td></tr>`).join('')}</tbody></table></div><p>Categories and conditions retain their source wording. This is not a guarantee of a four-year completion date or course offering.</p><button class="btn primary" data-start-catalog-draft="${esc(id)}">Build a source-based planning draft →</button>`;target.querySelector('[data-start-catalog-draft]').onclick=()=>startCatalogDraft(id)}catch(error){if(target.isConnected)target.innerHTML=`<p role="alert">${esc(error.message)}</p>`}}
function bindCatalogPlanner(){document.querySelectorAll('[data-start-catalog-draft]').forEach(b=>b.onclick=()=>startCatalogDraft(b.dataset.startCatalogDraft));document.querySelectorAll('[data-wsu-requirements]').forEach(b=>b.onclick=()=>{let target=b.parentElement.querySelector('.wsu-requirements-reader');if(!target){target=document.createElement('section');target.className='wsu-requirements-reader degree-optimizer';b.parentElement.append(target)}showWSURequirements(b.dataset.wsuRequirements,target)});document.querySelectorAll('[data-catalog-row-options]').forEach(el=>el.onchange=()=>{state.catalogDraft.rows[+el.dataset.catalogRowOptions].selectedCodes=[...el.selectedOptions].map(o=>o.value).filter(Boolean);catalogPrepared=null;save()});document.querySelectorAll('[data-confirm-catalog-row]').forEach(el=>el.onchange=()=>{state.catalogDraft.rows[+el.dataset.confirmCatalogRow].confirmed=el.checked;catalogPrepared=null;save()});document.querySelector('#prepare-catalog-courses')?.addEventListener('click',prepareCatalogCourses)}
function installCatalogPlanner(){const previous=degreeGoalPanel;degreeGoalPanel=(goal,pool,result)=>previous(goal,pool,result)+(goal.unresolvedSourceClauses?.length?`<details class="plan-trust-alert"><summary>${goal.unresolvedSourceClauses.length} source clauses are not included in this automatic draft</summary>${goal.unresolvedSourceClauses.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`:'');const priorBind=bind;bind=()=>{priorBind();bindCatalogPlanner()}}
